-- Somente clone descartável: usa COMMIT para duas sessões.
do $$begin if current_database()<>'sso_foto_tomb_0986_tmp' then raise exception 'banco_descartavel_exigido'; end if;end$$;
create extension if not exists pgtap with schema extensions;
create extension if not exists dblink with schema extensions;
set search_path=public,extensions;
select plan(8);
begin;
set local app.auvo_sync_write='true';
insert into auth.users(id,instance_id,aud,role,email,encrypted_password,raw_app_meta_data,raw_user_meta_data,created_at,updated_at) values ('17987000-0000-0000-0000-000000000001','00000000-0000-0000-0000-000000000000','authenticated','authenticated','corrida-tombstone@example.test',crypt('x',gen_salt('bf')),'{}','{}',now(),now());
insert into config.usuarios(user_id,papel,nome,ativo) values ('17987000-0000-0000-0000-000000000001','colaborador','Corrida tombstone',true);
insert into config.usuario_modulos(user_id,modulo,nivel) values ('17987000-0000-0000-0000-000000000001','pcm','escrita');
insert into pcm.clientes(id,nome,ativo,created_by) values ('17987000-0000-0000-0000-00000000000a','Cliente corrida',true,'17987000-0000-0000-0000-000000000001');
insert into config.sso_concessoes(usuario_id,acao,cliente_id) values ('17987000-0000-0000-0000-000000000001','cadastro.aprovar','17987000-0000-0000-0000-00000000000a');
insert into pcm.sso_levantamentos(id,cliente_id,origem,chave_origem,conteudo,criado_por) values ('17987000-0000-0000-0000-000000000021','17987000-0000-0000-0000-00000000000a','manual','corrida-tombstone','[]','17987000-0000-0000-0000-000000000001');
insert into pcm.sso_levantamento_linhas(lote_id,chave,tipo,atributos) values ('17987000-0000-0000-0000-000000000021','a','sistema','{}');
update pcm.sso_ingestao_foto_gate set habilitado=true where id;
update pcm.sso_fotos_levantamento_gate set habilitado=true where id;
commit;
select extensions.dblink_connect('tomb_a','dbname='||current_database());select extensions.dblink_connect('tomb_b','dbname='||current_database());
select extensions.dblink_exec('tomb_a','begin');select extensions.dblink_exec('tomb_b','begin');
select extensions.dblink_exec('tomb_a',$sql$set local request.jwt.claims='{"sub":"17987000-0000-0000-0000-000000000001","role":"authenticated","user_role":"colaborador"}'$sql$);
select extensions.dblink_exec('tomb_a','set local role authenticated');select extensions.dblink_exec('tomb_b','set local role service_role');select extensions.dblink_exec('tomb_b','set local application_name = ''s178_tomb_b''');
select r from extensions.dblink('tomb_a',$sql$select pcm.sso_cancelar_ingestao_foto('17987000-0000-0000-0000-00000000000a','17987000-0000-0000-0000-000000000041','17987000-0000-0000-0000-000000000021','a','Não recebido')$sql$) as t(r jsonb);
select extensions.dblink_send_query('tomb_b',$sql$select pcm.sso_ingestao_foto_servico('reservar','17987000-0000-0000-0000-000000000001','17987000-0000-0000-0000-000000000041','17987000-0000-0000-0000-000000000021','a',repeat('a',64),null)$sql$);
do $$begin for i in 1..100 loop perform pg_stat_clear_snapshot();exit when exists(select 1 from pg_stat_activity where datname=current_database() and application_name='s178_tomb_b' and wait_event_type='Lock');perform pg_sleep(0.01);end loop;end$$;
select ok(exists(select 1 from pg_stat_activity where datname=current_database() and application_name='s178_tomb_b' and wait_event_type='Lock'),'reserva aguarda cancelamento');
select extensions.dblink_exec('tomb_a','commit');select count(*) from extensions.dblink_get_result('tomb_b',false) as t(r jsonb);
select matches(extensions.dblink_error_message('tomb_b'),'ingestao_cancelada','reserva tardia recusada');select count(*) from extensions.dblink_get_result('tomb_b',false) as t(r jsonb);select extensions.dblink_exec('tomb_b','rollback');
select is((select count(*)::integer from pcm.sso_ingestao_foto_reservas where request_id='17987000-0000-0000-0000-000000000041'),0,'sem reserva tardia');
select is((select count(*)::integer from pcm.sso_ingestao_foto_tombstones where request_id='17987000-0000-0000-0000-000000000041'),1,'tombstone único');
select extensions.dblink_exec('tomb_a','begin');select extensions.dblink_exec('tomb_b','begin');
select extensions.dblink_exec('tomb_a','set local role service_role');select extensions.dblink_exec('tomb_b','set local application_name = ''s178_tomb_b''');
select extensions.dblink_exec('tomb_b',$sql$set local request.jwt.claims='{"sub":"17987000-0000-0000-0000-000000000001","role":"authenticated","user_role":"colaborador"}'$sql$);select extensions.dblink_exec('tomb_b','set local role authenticated');
select r from extensions.dblink('tomb_a',$sql$select pcm.sso_ingestao_foto_servico('reservar','17987000-0000-0000-0000-000000000001','17987000-0000-0000-0000-000000000042','17987000-0000-0000-0000-000000000021','a',repeat('b',64),null)$sql$) as t(r jsonb);
select extensions.dblink_send_query('tomb_b',$sql$select pcm.sso_cancelar_ingestao_foto('17987000-0000-0000-0000-00000000000a','17987000-0000-0000-0000-000000000042','17987000-0000-0000-0000-000000000021','a','Não recebido')$sql$);
do $$begin for i in 1..100 loop perform pg_stat_clear_snapshot();exit when exists(select 1 from pg_stat_activity where datname=current_database() and application_name='s178_tomb_b' and wait_event_type='Lock');perform pg_sleep(0.01);end loop;end$$;
select ok(exists(select 1 from pg_stat_activity where datname=current_database() and application_name='s178_tomb_b' and wait_event_type='Lock'),'cancelamento aguarda reserva');
select extensions.dblink_exec('tomb_a','commit');create temporary table tomb_resultado as select r from extensions.dblink_get_result('tomb_b') as t(r jsonb);select count(*) from extensions.dblink_get_result('tomb_b') as t(r jsonb);select extensions.dblink_exec('tomb_b','commit');
select is((select r->>'estado' from tomb_resultado),'cancelada','reserva concorrente foi cancelada');
select is((select count(*)::integer from pcm.sso_ingestao_foto_reservas where request_id='17987000-0000-0000-0000-000000000042' and cancelado_em is not null),1,'cancelamento persiste na reserva');
select is((select count(*)::integer from pcm.sso_fotos_levantamento where request_id in ('17987000-0000-0000-0000-000000000041','17987000-0000-0000-0000-000000000042')),0,'nenhuma foto confirmada');
select extensions.dblink_disconnect('tomb_a');select extensions.dblink_disconnect('tomb_b');select * from finish();
